{
  "status": "SUPPORTED",
  "task_summary": "Prepare living room seating and refreshment areas for two people, relocating the remote control to a central accessible position.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "refreshment_setting",
        "entity_kind": "OBJECT",
        "function": "Holds food or drink for a person",
        "required_count": 2,
        "binding_policy": "DISTINCT"
      , "candidate_categories": [
          "cup",
          "plate",
          "snack",
          "bowl"
        ],
        "required_properties": [
          "holds consumable"
        ]
      }
    ],
    "functional_relations": [
      {
        "id": "setting_near_seating",
        "relation": "Each refreshment setting is positioned near a seating area for a person.",
        "participant_roles": [
          "refreshment_setting",
          "seating_area"
        ]
      , "required": true
      }
    , {
        "id": "control_central_access",
        "relation": "The entertainment control is positioned in a central location accessible to all seated people.",
        "participant_roles": [
          "entertainment_control",
          "surface"
        ]
      , "required": true
      }
    ]
  , "operation_pairings": [
      {
        "id": "provide_refreshment_setting",
        "operation": "Place a refreshment setting on a surface near seating.",
        "participant_roles": [
          "refreshment_setting",
          "surface"
        ],
        "operation_count": 2
      }
    , {
        "id": "move_entertainment_control",
        "operation": "Move the entertainment control to a central surface.",
        "participant_roles": [
          "entertainment_control",
          "surface"
        ],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "refreshment_setting": [
        {"label": "Cups and plates", "visual_description": "Visible on the wooden desk in the foreground."}
      ],
      "entertainment_control": [
        {"label": "Remote", "visual_description": "Visible on the wooden desk in the foreground."}
      ],
      "surface": [
        {"label": "Coffee table", "visual_description": "Central table with light top."},
        {"label": "Side tables", "visual_description": "Two small tables next to the armchairs."},
        {"label": "Desk", "visual_description": "Large wooden desk in foreground."},
        {"label": "Console table", "visual_description": "Table under the television."}
      ],
      "seating_area": [
        {"label": "Armchairs", "visual_description": "Two black armchairs."}
      ],
      "television": [
        {"label": "TV Screen", "visual_description": "Black screen mounted on the wall."}
      ]
    },
    "inspectable_regions": [
      {
        "id": "wooden_desk",
        "label": "Foreground Desk",
        "visual_description": "Contains current refreshments and remote.",
        "reason": "Likely source of items to be moved; contains clutter."
      },
      {
        "id": "coffee_table",
        "label": "Central Coffee Table",
        "visual_description": "Empty, central position.",
        "reason": "Ideal central location for shared entertainment control access."
      },
      {
        "id": "side_tables",
        "label": "Side Tables",
        "visual_description": "Next to chairs, currently empty.",
        "reason": "Suitable locations for individual refreshment settings."
      },
      {
        "id": "console_table",
        "label": "Console Under TV",
        "visual_description": "Long table under the screen.",
        "reason": "May contain additional equipment or be a destination for media."
      }
    ],
    "inspection_order": [
      "wooden_desk",
      "coffee_table",
      "side_tables",
      "console_table"
    ]
  }
  , "unsupported_reason": ""
  , "schema_version": 3
}
